create or replace function private.service_titan_job_brief(p_job_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_customer text; v_location text; begin if not public.has_permission_for_current_user('view_jobs') then raise exception 'Jobs permission required'; end if; select payload->>'customerId',payload->>'locationId' into v_customer,v_location from public.service_titan_records where resource='jobs' and external_id=p_job_id limit 1; return jsonb_build_object('job',(select payload from public.service_titan_records where resource='jobs' and external_id=p_job_id limit 1),'customer',(select payload from public.service_titan_records where resource='customers' and external_id=v_customer limit 1),'location',(select payload from public.service_titan_records where resource='locations' and external_id=v_location limit 1),'appointments',coalesce((select jsonb_agg(payload order by nullif(payload->>'start','') desc nulls last) from public.service_titan_records where resource='appointments' and payload->>'jobId'=p_job_id),'[]'::jsonb),'memberships',coalesce((select jsonb_agg(payload order by nullif(payload->>'from','') desc nulls last) from public.service_titan_records where resource='memberships' and payload->>'customerId'=v_customer),'[]'::jsonb),'priorJobs',coalesce((select jsonb_agg(payload order by nullif(payload->>'completedOn','') desc nulls last) from (select payload from public.service_titan_records where resource='jobs' and payload->>'customerId'=v_customer and external_id<>p_job_id order by nullif(payload->>'completedOn','') desc nulls last limit 5) q),'[]'::jsonb),'lifetimeRevenue',coalesce((select sum(case when coalesce(payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (payload->>'total')::numeric else 0 end) from public.service_titan_records where resource='invoices' and coalesce(payload->'customer'->>'id',payload->>'customerId')=v_customer),0),'openBalance',coalesce((select sum(case when coalesce(payload->>'balance','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (payload->>'balance')::numeric else 0 end) from public.service_titan_records where resource='invoices' and coalesce(payload->'customer'->>'id',payload->>'customerId')=v_customer),0)); end $$;
create or replace function public.service_titan_job_brief(p_job_id text) returns jsonb language sql stable set search_path='' as $$ select private.service_titan_job_brief(p_job_id) $$; revoke all on function public.service_titan_job_brief(text) from public,anon; grant execute on function public.service_titan_job_brief(text) to authenticated;